    C c;
    constructor() { c = new C(address(new Log())); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function test(uint a1, uint a2) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (a1 + 2 ether) + (a2 + 2 ether));
        require(a1 + 2 ether > c.MinDeposit());
        require(a2 + 2 ether > c.MinDeposit());
        require(a1 + a2 <= type(uint256).max - 4 ether);
        require(a1 + a2 + 4 ether <= type(uint256).max / 2);
        require(address(this).balance >= a1 + a2 + 2 ether + 2 ether);
        c.Deposit{value: a1 + 2 ether}(); if (__ESBMC_reverted()) return;
        c.Deposit{value: a2 + 2 ether}(); if (__ESBMC_reverted()) return;
        assert(c.balances(address(this)) == (a1 + 2 ether) + (a2 + 2 ether));
    }
    receive() external payable {}
    fallback() external payable {}
}

