// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Private_Bank} from "../src/Private_Bank.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Private_Bank c;

    function setUp() public {
        c = new Private_Bank();
    }

    function _test(uint256 a1, uint256 a2) internal {
        vm.assume(a1 + 2 ether > c.MinDeposit());
        vm.assume(a2 + 2 ether > c.MinDeposit());
        vm.assume(a1 + a2 <= type(uint256).max - 4 ether);
        vm.assume(a1 + a2 + 4 ether <= type(uint256).max / 2);
        vm.assume(address(this).balance >= a1 + a2 + 2 ether + 2 ether);
        c.Deposit{value: a1 + 2 ether}();
        c.Deposit{value: a2 + 2 ether}();
        assertTrue(c.balances(address(this)) == (a1 + 2 ether) + (a2 + 2 ether));
    }

    function testFuzz_test(uint256 a1, uint256 a2) public {
        _test(a1, a2);
    }

    receive() external payable {}

    fallback() external payable {}
}
